        'candu_nuclear_reactors_title': 'CANDU nuclear reactors',
        'candu_nuclear_reactors_bullet1': '<strong>Canada has developed a unique nuclear reactor technology called CANDU,</strong> for CANada Deuterium Uranium. Canada is one of roughly half a dozen countries that offer domestically designed reactors to the open commercial market.',
        'candu_nuclear_reactors_bullet2': 'The CANDU reactor is a pressurized heavy water reactor (PHWR) that uses heavy water (deuterium oxide) as a moderator and coolant and natural uranium for fuel. The majority of power reactors in use in the world are light water reactors (LWR), which use normal water as the moderator and coolant and enriched uranium for fuel.',
        'candu_nuclear_reactors_bullet3': 'There are 17 CANDU reactors operating in Canada, and nine operating in five other countries. These 26 reactors represent nearly 7% of global reactors and 5% of global nuclear electricity capacity (17.9 GWe).',
        'candu_nuclear_reactors_bullet4': 'CANDU reactor refurbishment in Ontario is one of the largest infrastructure projects in Canada and will extend the life of Ontario\u2019s nuclear fleet past mid-century.',
