        'oil_sands_mining_title': 'Mining method',
        'oil_sands_mining_intro_1': 'Process: Companies use trucks and shovels to scoop oil sands from the ground. The oil sands are then transported to extraction plants where bitumen is separated from the sand by using steam. Tailings are then pumped into settling basins.',
        'oil_sands_mining_intro_2': 'In 2025, <strong>seven projects in Alberta</strong> produced <strong>1,767 Mb/d</strong>: CNRL Horizon Mine (<strong>317 Mb/d</strong>), Syncrude Mining Project (<strong>313 Mb/d</strong>), Imperial\'s Kearl (<strong>298 Mb/d</strong>), Suncor Base Mine (<strong>262 Mb/d</strong>), Fort Hills Mine (<strong>183 Mb/d</strong>), CNRL\'s Muskeg Mine (<strong>179 Mb/d</strong>) and Jackpine Mine (<strong>145 Mb/d</strong>).',
        'oil_sands_mining_infographic_aria': 'Infographic showing surface mining of oil sands with trucks and shovels, formation depth of 75 metres or less, 48% of current production and roughly 20% of oil sands resources.',
