        'oil_sands_in_situ_title': 'In situ method',
        'oil_sands_in_situ_intro_1': 'Process: Companies drill vertical and/or horizontal wells to inject steam to facilitate the flow of oil.',
        'oil_sands_in_situ_intro_2': '<strong>More than 20 projects in Alberta –</strong> The largest projects in 2025 were Firebag and MacKay River (Suncor) at <strong>278 Mb/d</strong>, Christina Lake (Cenovus) at <strong>230 Mb/d</strong>, Foster Creek (Cenovus) at <strong>206 Mb/d</strong> and Cold Lake (Imperial Oil) at <strong>156 Mb/d</strong>.',
        'oil_sands_in_situ_infographic_aria': 'Infographic showing in situ oil sands extraction with steam injection wells, formations deeper than 75 metres, 52% of current production and roughly 80% of oil sands resources.',
