        'hydrogen_industry_title': 'Hydrogen industry in Canada',
        'hydrogen_industry_bullet1': 'Canada is <strong>one of the top 10 hydrogen producers in the world today, with an estimated 4 Mt</strong> of hydrogen produced per year (low-carbon and carbon-intensive).',
        'hydrogen_industry_bullet2': 'Most hydrogen in Canada is produced from natural gas and used by the chemical industry and the oil and gas sector. Some of this hydrogen is now being produced using carbon abatement technologies, with several facilities already producing low-carbon hydrogen and others coming online soon.',
        'hydrogen_industry_bullet3': 'Air Liquide\'s <strong>20 MW</strong> electrolyser is <strong>Canada\'s largest electrolysis</strong> facility, producing low-carbon hydrogen using electricity to split water. Canada\'s total deployed low-carbon hydrogen production capacity is currently <strong>over 12,000 tonnes</strong> per year.',
        'hydrogen_industry_bullet4': 'There are more than <strong>100 established hydrogen and fuel cell companies</strong> spanning the full value chain, <strong>employing almost 4,300 people</strong> in direct jobs within Canada, and generating <strong>revenues in excess of $525 million</strong> and <strong>investing $125 million in research, development and demonstration.</strong>',
        'hydrogen_industry_infographic_aria': 'Illustration of hydrogen production and use in Canada, including refuelling, laboratory research and industrial applications.',
        'hydrogen_industry_footer_page': '102',
