        'hydrogen_title': 'Hydrogen',
        'hydrogen_intro_1': 'Hydrogen is a versatile energy carrier that can be produced from a variety of feedstocks.',
        'hydrogen_intro_2': 'Hydrogen can be converted to electricity through a fuel-cell in electric vehicles and power generation equipment, combusted to produce heat, or used as a feedstock in a range of chemical and industrial processes.',
        'hydrogen_intro_3': 'Hydrogen produced via low-carbon production pathways such as electrolysis or natural gas using carbon abatement can be ideal for decarbonizing hard-to-abate sectors such as heavy industry, truck freight or bus transit.',
        'hydrogen_feature_versatile': 'Versatile energy carrier',
