        'crude_prices_title': 'Prices',
        'crude_prices_subtitle_wti_wcs': 'West Texas intermediate (WTI) and Western Canadian Select (WCS)',
        'crude_prices_bullet_wti': 'WTI is a reference price for light crude oil delivered at Cushing, Oklahoma (a major pipeline hub) and is used as the benchmark price for North American crudes. WTI underlies oil futures contracts on the NYMEX.',
        'crude_prices_bullet_wcs': 'WCS is the main benchmark price for Canadian heavy crude, specifies delivery at Hardisty, Alberta and is representative of the price of oil from the oil sands.',
        'crude_prices_subtitle_differential': 'WTI-WCS differential',
        'crude_prices_bullet_diff_quality': 'WCS is typically sold at a discount to WTI due to differences in quality and transportation costs. Heavy crude is more difficult to process and requires specialized equipment at refineries.',
        'crude_prices_bullet_diff_history': 'The WCS-WTI differential has historically averaged between US$10-$15 per barrel. However, during the fall of 2018, the differential reached a record high of over US$50 per barrel due to insufficient pipeline capacity.',
        'crude_prices_bullet_pandemic': 'In Q2 2020, oil prices collapsed due to the drop in demand resulting from the global pandemic. US refineries drastically reduced their refinery runs and purchases of Canadian heavy crude.',
        'crude_prices_paragraph_recovery': 'Starting in Q3 2020, easing lockdown measures led to a demand recovery and a price rebound that lasted through 2021, accelerating in the first half of 2022 following the Russian invasion of Ukraine. After peaking in June 2022, prices trended downward due to increasing global inventories and concerns over slowing demand amid rising interest rates.',
        'crude_prices_chart_title': 'WTI and WCS prices',
        'crude_prices_yaxis_label': 'US dollars per barrel',
        'crude_prices_legend_differential': 'Differential',
