        'canadian_energy_production_para1': "L'énergie primaire est celle que l'on trouve dans la nature, avant qu'elle ne soit traitée ou convertie. Le <em>Cahier d'information sur l'énergie</em> calcule la production d'énergie primaire au moyen de deux méthodes. La première traite l'énergie de l'uranium comme une énergie primaire et tient donc compte de l'uranium produit et exporté par le Canada. Cette méthode présente un portait plus juste de la production d'énergie au Canada.",
        'canadian_energy_production_para2': "La deuxième méthode, qui est également employée par l'Agence internationale de l'énergie (AIE) et l'Energy Information Administration (EIA), entre autres, traite la production nationale d'électricité à partir d'énergie nucléaire comme une énergie primaire, mais pas l'uranium en soi. L'uranium est dense en énergie et le Canada exporte la majorité de sa production, ce qui explique pourquoi les deux méthodes produisent des résultats si disparates.",

