        'clean_technology_economy_bullet1': 'En 2017, le gouvernement du Canada a investi dans l\'élaboration d\'une stratégie pancanadienne sur les données de technologies propres dans le but d\'établir les bases de la mesure des impacts économiques, environnementaux et sociaux des technologies propres au Canada.',
        'clean_technology_economy_bullet2': 'Dans le cadre de cette stratégie, Statistique Canada a créé le Compte économique des produits environnementaux et de technologies propres (CEPETP) qui dresse un portrait complet de l\'état de l\'économie canadienne des technologies propres pour les années 2007 à 2023.',
        'clean_technology_economy_bullet3': 'Le CEPETP comprend des processus, des produits et des services qui réduisent les impacts environnementaux grâce à des activités de protection de l\'environnement, des activités de gestion des ressources et l\'utilisation de biens qui ont été adaptés pour consommer moins en énergie ou en ressources que la norme de l\'industrie.',
        'clean_technology_economy_infographic_aria': 'Infographie illustrant la relation entre le secteur de l\'énergie, les technologies énergétiques propres et les technologies propres, incluant les sources d\'énergie, les technologies renouvelables, le transport, l\'efficacité énergétique et les applications environnementales.',
        'clean_technology_economy_download_png': 'Télécharger l\'infographie en PNG',
        'clean_technology_economy_download_title': 'Les technologies propres et l\'économie',

