        'candu_nuclear_reactors_title': 'Réacteurs nucléaires CANDU',
        'candu_nuclear_reactors_bullet1': 'Le Canada a mis au point une technologie de réacteur nucléaire unique appelée <strong>CANDU</strong>, acronyme de CANada Deutérium Uranium. Le Canada fait partie d\u2019environ une demi-douzaine de pays proposant au marché commercial ouvert des réacteurs conçus au pays.',
        'candu_nuclear_reactors_bullet2': 'Le réacteur CANDU est un réacteur à eau lourde sous pression (RELP) qui se sert d\u2019eau lourde (oxyde de deutérium) comme modérateur et réfrigérant, et d\u2019uranium naturel comme carburant. La majorité des réacteurs de puissance en service dans le monde sont des réacteurs à eau légère (REL) qui utilisent de l\u2019eau normale comme modérateur et réfrigérant, et de l\u2019uranium enrichi comme carburant.',
        'candu_nuclear_reactors_bullet3': 'Il y a 17 réacteurs CANDU en opération au Canada et neuf dans cinq autres pays. Ces 26 réacteurs représentent près de 7\u00a0% des réacteurs mondiaux et 5\u00a0% de la capacité mondiale de production d\u2019électricité nucléaire (17,9 GWe).',
        'candu_nuclear_reactors_bullet4': 'La remise en état des réacteurs CANDU en Ontario est l\u2019un des plus grands projets d\u2019infrastructure au Canada et permettra de prolonger la durée de vie des centrales nucléaires de l\u2019Ontario au-delà du milieu du siècle.',
        'candu_nuclear_reactors_callout_heading': 'réacteurs nucléaires CANDU',
        'candu_nuclear_reactors_callout_suffix': 'sont en opération à l\u2019étranger.',
        'candu_nuclear_reactors_callout_aria': 'Neuf réacteurs nucléaires CANDU sont en opération à l\u2019étranger, en Argentine, en Roumanie, en Inde, en Chine et en Corée du Sud.',
