        'biofuels_transportation_bullet1': 'Les biocarburants liquides sont des carburants am\u00e9lior\u00e9s d\u00e9riv\u00e9s de la biomasse pouvant se pr\u00e9senter sous une forme liquide comme l\u2019\u00e9thanol ou les diesels renouvelables. Les biocarburants liquides sont m\u00e9lang\u00e9s \u00e0 de l\u2019essence et \u00e0 du diesel classiques et permettent de r\u00e9duire les \u00e9missions de gaz \u00e0 effet de serre associ\u00e9es aux m\u00e9langes de carburants.',
