        'oil_sands_mining_title': 'Méthode de forage',
        'oil_sands_mining_intro_1': 'Processus : Les compagnies utilisent des camions et des pelles pour extraire les sables bitumineux du sol. Les sables bitumineux sont ensuite transportés vers des usines d\'extraction où le bitume est séparé du sable à l\'aide de vapeur. Les résidus sont ensuite pompés dans des bassins de décantation.',
        'oil_sands_mining_intro_2': 'En 2025, <strong>sept projets miniers en Alberta</strong> produisaient <strong>1 767 kb/j</strong> : mine Horizon de CNRL (<strong>317 kb/j</strong>), projet minier Syncrude (<strong>313 kb/j</strong>), mine Kearl de la Pétrolière Impériale (<strong>298 kb/j</strong>), mine de base Suncor (<strong>262 kb/j</strong>), mine Fort Hills (<strong>183 kb/j</strong>), mine Muskeg de CNRL (<strong>179 kb/j</strong>) et Jackpine (<strong>145 kb/j</strong>).',
        'oil_sands_mining_infographic_aria': 'Infographie montrant l\'exploitation minière des sables bitumineux à l\'aide de camions et de pelles, formations d\'une profondeur de 75 mètres ou moins, 48 % de la production actuelle et environ 20 % des ressources de sables bitumineux.',
