        'oil_sands_in_situ_intro_1': 'Processus : Forage de puits verticaux ou horizontaux pour injection de vapeur pour faciliter l\'écoulement du pétrole.',
        'oil_sands_in_situ_intro_2': '<strong>Plus de 20 projets en Alberta :</strong> Les projets les plus importants en date de 2025 sont les projets Firebag et MacKay River (Suncor) à <strong>278 kb/j</strong>, Christina Lake (Cenovus) à <strong>230 kb/j</strong>, Foster Creek (Cenovus) à <strong>206 kb/j</strong> et Cold Lake (Imperial Oil) à <strong>156 kb/j</strong>.',
        'oil_sands_in_situ_infographic_aria': 'Infographie montrant l\'extraction in situ des sables bitumineux par injection de vapeur, formations d\'une profondeur supérieure à 75 mètres, 52 % de la production actuelle et environ 80 % des ressources de sables bitumineux.',
