        'hydrogen_industry_title': 'Industrie de l\'hydrogène au Canada',
        'hydrogen_industry_bullet1': 'Le Canada est aujourd\'hui <strong>l\'un des 10 premiers producteurs d\'hydrogène</strong> dans le monde, <strong>avec une production estimée à 4 Mt</strong> d\'hydrogène produit chaque année (à faible teneur en carbone et à forte teneur en carbone).',
        'hydrogen_industry_bullet2': 'Au Canada, la majeure partie de l\'hydrogène est produite à partir de gaz naturel et utilisée par l\'industrie chimique ainsi que par le secteur pétrolier et gazier. Une partie de cet hydrogène est désormais produite à l\'aide des technologies de réduction de carbone, avec plusieurs installations qui produisent déjà de l\'hydrogène à faible teneur en carbone et d\'autres qui entreront bientôt en service.',
        'hydrogen_industry_bullet3': 'Air Liquide a un électrolyseur de <strong>20 MW qui est la plus grande installation d\'électrolyse du Canada</strong>, produisant de l\'hydrogène bas carbone en utilisant l\'électricité pour la séparation de l\'eau. La capacité totale de production d\'hydrogène à faible teneur en carbone déployée au Canada dépasse actuellement <strong>12 000 tonnes par an</strong>.',
        'hydrogen_industry_bullet4': 'Il existe plus de <strong>100 entreprises de l\'hydrogène et des piles à combustible</strong> établies sur toute la chaîne de valeur, <strong>employant 4 300 personnes</strong> en emploi direct au Canada, générant <strong>plus de 525 millions de dollars de revenus</strong> et <strong>investissant 125 millions de dollars en recherche, développement et démonstration</strong>.',
        'hydrogen_industry_infographic_aria': 'Illustration de la production et de l\'utilisation de l\'hydrogène au Canada, incluant le ravitaillement, la recherche en laboratoire et les applications industrielles.',
        'hydrogen_industry_footer_page': '102',
