        'hydrogen_title': 'Hydrogène',
        'hydrogen_intro_1': 'L\'hydrogène est un vecteur d\'énergie polyvalent qui peut être produit à partir d\'une variété de matières premières.',
        'hydrogen_intro_2': 'L\'hydrogène peut être converti en électricité grâce à une pile à combustible dans les véhicules électriques et les équipements de production d\'électricité, brûlé pour produire de la chaleur ou utilisé comme matière première dans une gamme de procédés chimiques et industriels.',
        'hydrogen_intro_3': 'L\'hydrogène produit par des voies de production à faible teneur en carbone telles que l\'électrolyse ou le gaz naturel utilisant la réduction du carbone peut être idéal pour décarboner les secteurs difficiles à réduire tels que l\'industrie lourde, le transport par camion ou le transport en commun par autobus.',
