        'crude_prices_title': 'Prix',
        'crude_prices_subtitle_wti_wcs': 'West Texas intermediate (WTI) et Western Canadian Select (WCS)',
        'crude_prices_bullet_wti': 'Le WTI est un prix de référence pour le pétrole brut léger livré à Cushing, en Oklahoma (un carrefour pipelinier important) et est utilisé comme prix de référence pour le pétrole brut d\'Amérique du Nord. Le WTI est la base des contrats à terme sur le pétrole sur le NYMEX.',
        'crude_prices_bullet_wcs': 'Le WCS est un prix de référence pour le pétrole brut lourd (p. ex., le bitume fluidifié) livré à Hardisty, en Alberta. Le WCS est représentatif du prix du pétrole provenant des sables bitumineux.',
        'crude_prices_subtitle_differential': 'Le différentiel WCS-WTI',
        'crude_prices_bullet_diff_quality': 'Le WCS est généralement vendu à un prix inférieur au WTI en raison des différences de qualité et de coûts de transport. Le brut lourd est plus difficile à traiter et nécessite un équipement spécialisé dans les raffineries.',
        'crude_prices_bullet_diff_history': 'Le différentiel entre le WCS et le WTI est en moyenne entre 10 et 15 dollars US le baril. Toutefois, au cours de l\'automne 2018, l\'écart a atteint un niveau record de plus de 50 USD par baril en raison d\'une capacité pipelinière insuffisante.',
        'crude_prices_bullet_pandemic': 'Dans le deuxième trimestre de 2020, les prix du pétrole brut ont chuté en raison de l\'effondrement de la demande causée par la pandémie mondiale. Les raffineries américaines ont drastiquement réduit leurs activités et leurs commandes de pétrole brut lourd canadien.',
        'crude_prices_paragraph_recovery': 'À partir du T3 2020, l\'assouplissement des mesures de confinement a conduit à une reprise de la demande et à une hausse des prix qui a duré tout au long de 2021, s\'accélérant au cours du premier semestre de 2022 à la suite de l\'invasion russe de l\'Ukraine. Après avoir atteint un sommet en juin 2022, les prix ont suivi une tendance à la baisse en raison de l\'augmentation des stocks mondiaux et des préoccupations concernant le ralentissement de la demande dans un contexte de hausse des taux d\'intérêt.',
        'crude_prices_chart_title': 'Prix du WTI et WCS',
        'crude_prices_yaxis_label': 'Dollars US par baril',
