        'oil_by_rail_title': 'Pétrole brut par voie ferrée',
        'oil_by_rail_para1': 'Au cours de la dernière décennie, les expéditions de pétrole par chemin de fer ont fortement varié, sous l\'effet des fluctuations des prix mondiaux du pétrole et de la capacité de transport disponible. Les exportations ont chuté de façon marquée en 2015-2016 dans un contexte de baisse des prix, puis ont bondi en 2018, les contraintes touchant les pipelines dans l\'Ouest canadien ayant entraîné un recours accru au transport ferroviaire.',
        'oil_by_rail_para2': 'Les exportations ont atteint un sommet de 412 Mb/j en février 2020, juste avant qu\'un repli des prix lié à la pandémie entraîne une forte baisse des volumes. Bien que les exportations aient brièvement rebondi, elles se sont depuis stabilisées à des niveaux inférieurs aux sommets précédents.',
        'oil_by_rail_para3': 'Les expéditions nationales de mazout et de pétrole brut, quant à elles, sont demeurées relativement stables depuis 2016.',
